# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::MetricsClient do
  # "The task gathers real signals: the monolith's own counters, and Timekeeping's write latency, write counts
  # and `503 reference_unavailable` counts from its `GET /internal/v1/metrics` endpoint, read with the service identity."
  it "reads the cross-company metrics only with the service token bearer and refuses to send any request without it" do
    token = SecureRandom.hex(24)
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 7, "windows" => [{ "window_start" => "2026-05-01T12:00:00Z", "writes" => 4,
                                              "reference_unavailable" => 1, "stale_generation" => 0,
                                              "latency_ms_sum" => 50, "latency_ms_buckets" => { "25" => 5 } }] }
      ]
    }
    metrics = stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{token}" })
      .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

    fetched = described_class.configured.fetch

    expect(metrics).to have_been_requested.once
    expect(fetched["companies"].pluck("company_id")).to eq([7])

    ENV["TIMEKEEPING_SERVICE_TOKEN"] = ""
    expect { described_class.configured.fetch }.to raise_error(Timekeeping::MetricsClient::Unavailable) { |error|
      expect(error.message).not_to include(token)
    }
    expect(metrics).to have_been_requested.once
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before&.fetch(key, nil) }
  end
end
